examples.sql:
SET VARIABLE feed = 'ws://localhost:8765/';
CALL radio_subscribe(getvariable('feed'));
CALL radio_listen(true, INTERVAL '5 seconds');
SELECT receive_time, decode(message) AS text
FROM radio_received_messages()
WHERE subscription_url = getvariable('feed');

CALL radio_transmit_message(
  getvariable('feed'), 'main',
  '{"type":"ack"}'::BLOB,
  3, INTERVAL '500 milliseconds'
);
SELECT transmit_successes, transmit_failures
FROM radio_subscriptions();

CALL radio_subscribe('loopback://t');
CALL radio_transmit_message('loopback://t',
  'orders', '{"value":43}', 3,
  INTERVAL '10 seconds');
CALL radio_listen(true, INTERVAL '2 seconds');
SELECT channel, decode(message) AS text
FROM radio_subscription_received_messages(
  'loopback://t');
